using Licitaciones.Application.Licitaciones;
using Licitaciones.Application.Proveedores;
namespace Licitaciones.Api.Endpoints.Crud;
public sealed record EditarLicitacionRequest(string Codigo, string Titulo, decimal PresupuestoEstimadoCrc, DateTimeOffset FechaCierre);
public sealed record EditarProveedorRequest(string Nombre);
public static class CrudEndpoints { public static IEndpointRouteBuilder MapCrud(this IEndpointRouteBuilder a) { var l = a.MapGroup("/api/v1/licitaciones"); l.MapGet("", async (GestionarLicitacionesService s, CancellationToken c) => Results.Ok(await s.ListarAsync(c))); l.MapGet("/{id:guid}", async (Guid id, GestionarLicitacionesService s, CancellationToken c) => Results.Ok(await s.ObtenerAsync(id, c))); l.MapPut("/{id:guid}", async (Guid id, EditarLicitacionRequest r, GestionarLicitacionesService s, CancellationToken c) => { await s.EditarAsync(id, r.Codigo, r.Titulo, r.PresupuestoEstimadoCrc, r.FechaCierre, c); return Results.NoContent(); }); l.MapDelete("/{id:guid}", async (Guid id, GestionarLicitacionesService s, CancellationToken c) => { await s.EliminarAsync(id, c); return Results.NoContent(); }); var p = a.MapGroup("/api/v1/proveedores"); p.MapGet("", async (GestionarProveedoresService s, CancellationToken c) => Results.Ok(await s.ListarAsync(c))); p.MapGet("/{id:guid}", async (Guid id, GestionarProveedoresService s, CancellationToken c) => Results.Ok(await s.ObtenerAsync(id, c))); p.MapPut("/{id:guid}", async (Guid id, EditarProveedorRequest r, GestionarProveedoresService s, CancellationToken c) => { await s.EditarAsync(id, r.Nombre, c); return Results.NoContent(); }); p.MapDelete("/{id:guid}", async (Guid id, GestionarProveedoresService s, CancellationToken c) => { await s.EliminarAsync(id, c); return Results.NoContent(); }); return a; } }
